<?php
declare(strict_types=1);

$root=dirname(__DIR__);$config=require $root.'/config/exercise_dataset.php';$options=getopt('',['dry-run','destination:']);$dryRun=array_key_exists('dry-run',$options);$destination=rtrim((string)($options['destination']??$root.'/storage/import-source/exercises-dataset'),'/\\');$commit='118e4bd6b14da6df0e36605d7169b65db18389a4';$base="https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/{$commit}/";$selected=[];foreach($config['groups'] as $ids)array_push($selected,...$ids);
$download=static function(string $url,string $path)use($dryRun):void{echo ($dryRun?'WOULD FETCH ':'FETCH ').$url."\n";if($dryRun)return;@mkdir(dirname($path),0775,true);$context=stream_context_create(['http'=>['timeout'=>60,'user_agent'=>'HomeGymExerciseImporter/1.0']]);$contents=@file_get_contents($url,false,$context);if($contents===false)throw new RuntimeException("Download failed: {$url}");if(file_put_contents($path,$contents)===false)throw new RuntimeException("Write failed: {$path}");};
try{$jsonPath=$destination.'/data/exercises.json';if(!is_file($jsonPath))$download($base.'data/exercises.json',$jsonPath);if($dryRun){echo "Would fetch the dataset JSON, then only media referenced by 80 selected records.\n";exit(0);}$records=json_decode((string)file_get_contents($jsonPath),true,512,JSON_THROW_ON_ERROR);$byId=[];foreach($records as $record)$byId[$record['id']]=$record;$files=0;foreach($selected as $id){if(!isset($byId[$id]))throw new RuntimeException("Missing selected exercise {$id}");foreach(['image','gif_url'] as $field){$relative=$byId[$id][$field]??null;if(!$relative)continue;$target=$destination.'/'.str_replace('/',DIRECTORY_SEPARATOR,$relative);if(!is_file($target))$download($base.$relative,$target);$files++;}}file_put_contents($destination.'/.dataset-commit',$commit."\n");echo "Dataset selection ready: ".count($selected)." exercises, {$files} media references.\n";}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
